#include "mspa/semantics/domain_pack.hpp"
#include <algorithm>
#include <cmath>
#include <set>
namespace mspa {
Result<void> validate_domain_pack(const DomainPack&p){if(!p.metadata.id.valid()||!p.metadata.name_space.valid()||p.metadata.name.empty())return make_error(ErrorCode::InvalidPack,"pack requires id, namespace and name");if(p.metadata.min_mspa_major>runtime_version_major)return make_error(ErrorCode::VersionMismatch,"pack requires newer MSPA major version");if(p.predicates.size()>4096||p.concepts.size()>8192||p.action_types.size()>4096||p.inference_rules.size()>4096)return make_error(ErrorCode::QuotaExceeded,"domain pack exceeds hard declaration limits");std::set<std::uint64_t> pred,actions;std::set<std::string> cons;for(const auto&s:p.predicates){if(!s.id.valid()||s.name_space!=p.metadata.name_space||!pred.insert(s.id.value()).second)return make_error(ErrorCode::InvalidPack,"invalid/duplicate predicate in pack");}for(const auto&a:p.action_types){if(!a.first.valid()||a.second.empty()||!actions.insert(a.first.value()).second)return make_error(ErrorCode::InvalidPack,"invalid/duplicate action type");}for(const auto&c:p.considerations){if(c.id.empty()||!std::isfinite(c.weight)||!cons.insert(c.id).second)return make_error(ErrorCode::InvalidPack,"invalid/duplicate consideration");}for(const auto&r:p.inference_rules){if(!r.id||!r.conclusion.valid())return make_error(ErrorCode::InvalidPack,"invalid inference rule");}for(const auto&v:p.initial_values)if(!v.first.valid()||!std::isfinite(v.second)||v.second<0.0f||v.second>1.0f)return make_error(ErrorCode::InvalidPack,"invalid initial value");return {};}
Result<void> apply_domain_pack(RegistryBuilder&b,const DomainPack&p){auto ok=validate_domain_pack(p);if(!ok)return *ok.error_if();for(const auto&s:p.predicates){auto r=b.add_predicate(s);if(!r)return *r.error_if();}for(const auto&c:p.concepts){auto r=b.add_concept(c.first,c.second);if(!r)return *r.error_if();}for(const auto&a:p.action_types){auto r=b.add_action_type(a.first,a.second);if(!r)return *r.error_if();}for(const auto&c:p.considerations){auto r=b.add_consideration(c);if(!r)return *r.error_if();}for(const auto&s:p.action_schemas){auto r=b.add_action_schema(s);if(!r)return *r.error_if();}for(const auto&r:p.inference_rules){InferenceRuleData d{};d.id=r.id;if(!r.structured_premises.empty())for(const auto&x:r.structured_premises)d.premises.push_back({x.predicate,x.positive});else for(auto x:r.premises)d.premises.push_back({x,true});d.conclusion=r.conclusion;d.conclusion_namespace=r.conclusion_namespace;d.conclusion_positive=r.conclusion_positive;d.base_certainty=r.base_certainty;auto q=b.add_inference_rule(std::move(d));if(!q)return *q.error_if();}for(const auto&v:p.initial_values){auto q=b.add_default_value(v.first,v.second);if(!q)return *q.error_if();}return b.mark_pack(p.metadata.id,p.metadata.version_major,p.metadata.version_minor,p.metadata.version_patch);}
}
